-- 052 - Conciliacion de Aviacion General 2025 contra el Excel autorizado.
-- Fuente: Aviacion General 2025 (1).xlsx, hoja Data.
-- SHA256: 7cf0c5440f82b452891907ba68341899146c5537ce08e9ee73248a1b942761aa
--
-- Alcance autorizado: incluir todas las filas reportadas, incluso repetidas,
-- manteniendolas PENDIENTES con el motivo documentado.
-- 7 filas incorporadas; 2 totales de pasajeros con desglose sin confirmar;
-- 11 horas corregidas desde fracciones Excel; 1 destino recuperado.
-- Los 18 registros de 9 grupos repetidos, los 2 totales contradictorios y
-- la hora ambigua de Data M1300 permanecen PENDIENTES de validacion.
-- Resultado: 3071 movimientos (1541 salidas, 1530 llegadas), 21114 pasajeros.
-- Requiere 051 para contar 2025 por fecha real.
-- Ejecutar primero con ROLLBACK; cambiar a COMMIT para aplicar.
-- No modifica otros anios. Es idempotente y rechaza cambios concurrentes.

BEGIN;
SET LOCAL statement_timeout = '60s';
LOCK TABLE public.aviacion_general_operaciones IN SHARE ROW EXCLUSIVE MODE;

