DO $contrato$
DECLARE r record; actual jsonb;
BEGIN
    FOR r IN SELECT * FROM ag25_cambios LOOP
        SELECT to_jsonb(o) INTO actual
          FROM public.aviacion_general_operaciones o WHERE o.id = r.id;
        IF actual IS NULL OR NOT (
            actual @> r.anterior OR actual @> (r.anterior || r.cambios)
        ) THEN
            RAISE EXCEPTION 'El registro % cambio desde la revision; se cancela todo.', r.id;
        END IF;
    END LOOP;
END
$contrato$;

UPDATE public.aviacion_general_operaciones o
SET
    hora_real = CASE WHEN c.cambios ? 'hora_real' THEN (jsonb_populate_record(NULL::public.aviacion_general_operaciones, c.cambios)).hora_real ELSE o.hora_real END,
    observaciones = CASE WHEN c.cambios ? 'observaciones' THEN (jsonb_populate_record(NULL::public.aviacion_general_operaciones, c.cambios)).observaciones ELSE o.observaciones END,
    hora_programada = CASE WHEN c.cambios ? 'hora_programada' THEN (jsonb_populate_record(NULL::public.aviacion_general_operaciones, c.cambios)).hora_programada ELSE o.hora_programada END,
    observacion_validacion = CASE WHEN c.cambios ? 'observacion_validacion' THEN (jsonb_populate_record(NULL::public.aviacion_general_operaciones, c.cambios)).observacion_validacion ELSE o.observacion_validacion END,
    aeropuerto_origen_destino = CASE WHEN c.cambios ? 'aeropuerto_origen_destino' THEN (jsonb_populate_record(NULL::public.aviacion_general_operaciones, c.cambios)).aeropuerto_origen_destino ELSE o.aeropuerto_origen_destino END,
    ciudad_origen_destino = CASE WHEN c.cambios ? 'ciudad_origen_destino' THEN (jsonb_populate_record(NULL::public.aviacion_general_operaciones, c.cambios)).ciudad_origen_destino ELSE o.ciudad_origen_destino END,
    adultos = CASE WHEN c.cambios ? 'adultos' THEN (jsonb_populate_record(NULL::public.aviacion_general_operaciones, c.cambios)).adultos ELSE o.adultos END,
    infantes = CASE WHEN c.cambios ? 'infantes' THEN (jsonb_populate_record(NULL::public.aviacion_general_operaciones, c.cambios)).infantes ELSE o.infantes END,
    pax_total_reportado = CASE WHEN c.cambios ? 'pax_total_reportado' THEN (jsonb_populate_record(NULL::public.aviacion_general_operaciones, c.cambios)).pax_total_reportado ELSE o.pax_total_reportado END,
    fecha_modificacion = now()
FROM ag25_cambios c
WHERE o.id = c.id AND NOT (to_jsonb(o) @> c.cambios);

CREATE TEMP TABLE ag25_nuevas ON COMMIT DROP AS
