DO $fuente$
BEGIN
    IF EXISTS (
        SELECT 1 FROM ag25_nuevas n
        JOIN public.aviacion_general_operaciones o
          ON o.hash_origen = n.hash_origen
          OR (o.archivo_origen = n.archivo_origen
              AND o.hoja_origen = n.hoja_origen AND o.fila_origen = n.fila_origen)
        WHERE NOT (to_jsonb(o) @> to_jsonb(n))
    ) THEN
        RAISE EXCEPTION 'Ya existe una fila de esta fuente con datos distintos; se cancela todo.';
    END IF;
END
$fuente$;

INSERT INTO public.aviacion_general_operaciones (folio_rotacion, fecha_operacion, tipo_operacion, ambito_operacion, operador, matricula, tipo_aeronave, aeropuerto_origen_destino, ciudad_origen_destino, hora_programada, hora_real, adultos, infantes, pax_od, estado, pais, tipo_fuente, archivo_origen, hoja_origen, fila_origen, hash_origen, estatus_registro, estado_validacion, observaciones, observacion_validacion)
SELECT n.folio_rotacion, n.fecha_operacion, n.tipo_operacion, n.ambito_operacion, n.operador, n.matricula, n.tipo_aeronave, n.aeropuerto_origen_destino, n.ciudad_origen_destino, n.hora_programada, n.hora_real, n.adultos, n.infantes, n.pax_od, n.estado, n.pais, n.tipo_fuente, n.archivo_origen, n.hoja_origen, n.fila_origen, n.hash_origen, n.estatus_registro, n.estado_validacion, n.observaciones, n.observacion_validacion
FROM ag25_nuevas n
WHERE NOT EXISTS (
    SELECT 1 FROM public.aviacion_general_operaciones o WHERE o.hash_origen = n.hash_origen
);

-- Verificacion: los 12 meses deben coincidir en ambas direcciones,
-- pasajeros y ambito. Los valores provienen de Data y de Ops/Pax A.G.
