DO $verificar$
DECLARE r record; actual jsonb; resumen jsonb; campo text; listado jsonb;
BEGIN
    FOR r IN SELECT key AS periodo, value AS esperado FROM ag25_meses LOOP
        SELECT jsonb_build_object(
            'movimientos',count(*),
            'llegadas',count(*) FILTER (WHERE tipo_operacion='LLEGADA'),
            'salidas',count(*) FILTER (WHERE tipo_operacion='SALIDA'),
            'pax',COALESCE(sum(pax_ag),0),
            'pax_llegada',COALESCE(sum(pax_ag) FILTER (WHERE tipo_operacion='LLEGADA'),0),
            'pax_salida',COALESCE(sum(pax_ag) FILTER (WHERE tipo_operacion='SALIDA'),0),
            'nacionales',count(*) FILTER (WHERE ambito_operacion='NACIONAL'),
            'internacionales',count(*) FILTER (WHERE ambito_operacion='INTERNACIONAL'),
            'pax_nacional',COALESCE(sum(pax_ag) FILTER (WHERE ambito_operacion='NACIONAL'),0),
            'pax_internacional',COALESCE(sum(pax_ag) FILTER (WHERE ambito_operacion='INTERNACIONAL'),0)
        ) INTO actual
        FROM public.aviacion_general_operaciones
        WHERE estatus_registro='ACTIVO'
          AND fecha_operacion >= (r.periodo || '-01')::date
          AND fecha_operacion < (r.periodo || '-01')::date + INTERVAL '1 month';
        IF actual IS DISTINCT FROM r.esperado THEN
            RAISE EXCEPTION 'No cuadra %: actual %, esperado %',r.periodo,actual,r.esperado;
        END IF;
    END LOOP;

    resumen := public.aviacion_general_resumen(
        '{"fecha_desde":"2025-01-01","fecha_hasta":"2025-12-31"}'::jsonb
    );
    IF NOT (resumen->'totales' @> '{"movimientos":3071,"salidas":1541,"llegadas":1530,"pax":21114,"pax_salida":10525,"pax_llegada":10589,"nacionales":2350,"internacionales":721}'::jsonb) THEN
        RAISE EXCEPTION 'El tablero no coincide con el Excel: %',resumen->'totales';
    END IF;
    FOR r IN SELECT key AS periodo,value AS esperado FROM ag25_meses LOOP
        SELECT m INTO listado FROM jsonb_array_elements(resumen->'por_mes') m
        WHERE m->>'periodo'=r.periodo;
        FOREACH campo IN ARRAY ARRAY['movimientos','salidas','llegadas','pax','pax_salida','pax_llegada'] LOOP
            IF listado->campo IS DISTINCT FROM r.esperado->campo THEN
                RAISE EXCEPTION 'El tablero no cuadra en % / %',r.periodo,campo;
            END IF;
        END LOOP;
    END LOOP;
    IF EXISTS (
        SELECT 1 FROM ag25_cambios c
        LEFT JOIN public.aviacion_general_operaciones o ON o.id=c.id
        WHERE o.id IS NULL OR NOT(to_jsonb(o) @> (c.anterior || c.cambios))
    ) OR EXISTS (
        SELECT 1 FROM ag25_nuevas n
        LEFT JOIN public.aviacion_general_operaciones o ON o.hash_origen=n.hash_origen
        WHERE o.id IS NULL OR NOT(to_jsonb(o) @> to_jsonb(n))
    ) THEN
        RAISE EXCEPTION 'Alguna correccion o fila nueva no quedo como se verifico.';
    END IF;
    RAISE NOTICE '2025 conciliado: 3071 movimientos, 21114 pasajeros; 12 meses correctos.';
END
$verificar$;

SELECT public.aviacion_general_resumen(
    '{"fecha_desde":"2025-01-01","fecha_hasta":"2025-12-31"}'::jsonb
)->'totales' AS resumen_2025;

ROLLBACK;
